// Modo: Run Once for All Items

// 1) Leer input
const input = items[0].json;

// 2) Orden de meses (para mostrar nombre bonito)
const monthOrder = [
  "Enero","Febrero","Marzo","Abril","Mayo","Junio",
  "Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre",
];

// 3) Helper: parsear MonthlyGuide (acepta string, array u objeto suelto)
let monthlyGuideData = [];
try {
  let raw = input.MonthlyGuide;

  // Si no existe MonthlyGuide pero el propio input parece ser un evento válido,
  // armamos un arreglo con ese único evento.
  if (!raw && (input.category === "MonthlyGuide" || (typeof input.month === "number" && input.content))) {
    raw = [input];
  }

  const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  monthlyGuideData = Array.isArray(parsed)
    ? parsed
    : (parsed?.MonthlyGuide ?? []);
} catch (e) {
  console.log("Error parseando MonthlyGuide:", e.message);
  monthlyGuideData = [];
}

// 4) Helper: listado de eventos con formato (numérico) de MonthlyGuide
//    - month: 1..12
//    - type: 1 -> individual (usa content.day y content.title)
//    - type: 2 -> global (usa content.events: { "Título": {...}, ... })
function createEventList(data, currentMonthNum) {
  const monthName = monthOrder[currentMonthNum - 1];
  let message = `*¡Eventos de ${monthName}!* 📅\n\n`;

  // Filtrar por mes numérico
  const monthEvents = data.filter(i => Number(i.month) === currentMonthNum);

  const eventDaysDictionary = {};
  let counter = 1;
  const seen = new Set();

  if (!monthEvents.length) {
    message += `No hay eventos programados para ${monthName}.\n\n`;
  } else {
    message += "*Eventos del mes:*\n";

    // 4.1 Individuales únicos (type === 1), ordenar por día asc
    const indivs = monthEvents
      .filter(e => Number(e.type) === 1 && e?.content?.day && e?.content?.title)
      .map(e => ({ day: Number(e.content.day), title: String(e.content.title) }))
      .sort((a, b) => a.day - b.day);

    for (const ev of indivs) {
      if (seen.has(ev.title)) continue;
      seen.add(ev.title);
      eventDaysDictionary[String(counter)] = String(ev.day);
      message += `${counter}. 🗓 Día ${ev.day}: "${ev.title}"\n`;
      counter++;
    }

    // 4.2 Globales (type === 2) — sin día, enumerar títulos de content.events
    for (const e of monthEvents.filter(e => Number(e.type) === 2 && e?.content?.events)) {
      const titles = Object.keys(e.content.events || {});
      for (const title of titles) {
        if (seen.has(title)) continue;
        seen.add(title);
        eventDaysDictionary[String(counter)] = "0";
        message += `${counter}. 🌍 "${title}"\n`;
        counter++;
      }
    }
  }

  message += `\n*¿Qué evento te gustaría conocer más a fondo?* Escribe el número correspondiente.`;
  return { message, eventDaysDictionary };
}

// 5) Mes actual (numérico 1–12) e invocar
const currentMonthNum = new Date().getMonth() + 1;
const { message, eventDaysDictionary } = createEventList(monthlyGuideData, currentMonthNum);

// 6) Devolver resultados
return [{
  json: {
    salida_whatsapp_guardian_function: {
      mensaje_guardian_options: message,
      dias_eventos_enumerados: eventDaysDictionary,
    }
  }
}];

