    lines.push(`⏰ ${hasStart ? c.start_time : "—"}${hasEnd ? "–" + c.end_time : ""}`);
  }

  // Lugar
  if (c.location) lines.push(`📍 ${c.location}`);

  // Descripción / texto
  const desc = c.description || c.text;
  if (desc) {
    lines.push("");
    lines.push(desc);
  }

  lines.push("");
  lines.push("¡Esperamos contar con tu participación en este evento! 🌟");

  return lines.join("\n");
}

// 7) Aux: obtener detalles según número seleccionado (orden por día)
function getEventDetails(data, monthNum, selRaw) {
  const total = countTotalEvents(data, monthNum);
  const v = validateSelectedEvent(selRaw, total);
  if (!v.isValid) {
    return { mensaje: v.error, imagen_url: null, error: "si" };
  }

  // Filtrar y ordenar solo individuales (type === 1) del mes actual por día asc
  const indivs = data
    .filter(i =>
      Number(i?.month) === Number(monthNum) &&
      Number(i?.type) === 1 &&
      i?.content?.day
    )
    .sort((a, b) => Number(a.content.day) - Number(b.content.day));

  const ev = indivs[v.value - 1];
  if (ev) {
    const mensaje = formatEventMessage(ev);
    const img = ev?.content?.image_url || null;
    return { mensaje, imagen_url: img, error: "no" };
  }

  // Fallback improbable
  return { mensaje: "Error inesperado al obtener los detalles del evento.", imagen_url: null, error: "si" };
}

// 8) Parsear MonthlyGuide (string, array, objeto, o un único evento suelto)
let monthlyGuideData = [];
try {
  let raw = rawMonthlyGuide;

  // Si no viene MonthlyGuide pero el input luce como un evento válido, lo envolvemos
  if (!raw && (input?.category === "MonthlyGuide" || (typeof input?.month === "number" && input?.content))) {
    raw = [input];
  }

  const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  monthlyGuideData = Array.isArray(parsed)
    ? parsed
    : (parsed?.MonthlyGuide ?? []);

  if (!Array.isArray(monthlyGuideData)) monthlyGuideData = [];
} catch (e) {
  return [{
    json: {
      salida_whatsapp_guardian_function: {
        mensaje_guardian_options: "Error al procesar los datos del calendario. Por favor, contacta al administrador.",
        imagen_url: null,
        error: "si"
      }
    }
  }];
}

// 9) Ejecutar lógica con mes actual numérico
